  const recipeOperand=object?.design??operand;const recipes=MATERIALS_RECIPES.filter(r=>r.a===recipeOperand||r.b===recipeOperand).map(r=>({...clone(r),partner:r.a===recipeOperand?r.b:r.a,available:s.known.includes(r.a)&&s.known.includes(r.b)}));
